export type Claim = {
  id: string
  text: string
  language: "sw" | "en" | "sheng" | "mixed"
  status: "pending" | "reviewed" | "verified" | "flagged"
}

export function groupByStatus(claims: Claim[]) {
  return claims.reduce<Record<string, Claim[]>>((acc, claim) => {
    acc[claim.status] = acc[claim.status] ?? []
    acc[claim.status].push(claim)
    return acc
  }, {})
}

const slangMap: Record<string, string> = {
  "noma": "excellent",
  "si": "not",
  "iko": "exists"
}

export function normalizeMixedText(input: string): string {
  return input
    .split(/\s+/)
    .map((w) => slangMap[w.toLowerCase()] ?? w)
    .join(" ")
}
